{
 'glossary': ['Glossary', 'Glossar'],
 'glossaryHint': ['Short explanations of the terms and abbreviations used in the app.', 'Kurze Erklärungen der Begriffe und Abkürzungen in der App.'],
 'termWhatIs': ['What does {term} mean?', 'Was bedeutet {term}?'],
 'termRpeTitle': ['RPE – Rating of Perceived Exertion', 'RPE – wahrgenommene Anstrengung'],
 'termRpeBody': ['How hard a workout or set felt, on a scale from 1 (very easy) to 10 (maximal). 3–4 = easy, you can chat; 6–7 = hard but controlled; 9–10 = all-out.', 'Wie anstrengend sich eine Einheit oder ein Satz angefühlt hat, auf einer Skala von 1 (sehr leicht) bis 10 (maximal). 3–4 = locker, du kannst dich unterhalten; 6–7 = fordernd, aber kontrolliert; 9–10 = absolutes Maximum.'],
 'termRpeTip': ['Optional. When you enter it, the plan adapts better – e.g. easy runs that feel too hard lead to a lighter next week.', 'Optional. Wenn du sie einträgst, passt sich der Plan genauer an – z. B. führen zu harte lockere Läufe zu einer leichteren nächsten Woche.'],
 'termRirTitle': ['RIR – Reps in Reserve', 'RIR – Wiederholungen im Tank'],
 'termRirBody': ['How many more reps you could have done at the end of a set. "2 in the tank" means you stop two reps before failure.', 'Wie viele Wiederholungen du am Ende eines Satzes noch geschafft hättest. „2 im Tank“ heißt: zwei Wiederholungen vor dem Muskelversagen aufhören.'],
 'termRirTip': ['The effort chips map to it: Easy ≈ 4+, Just right ≈ 2–3, Hard ≈ 1, Limit = 0. Most sets should end with 1–3 in the tank.', 'Die Effort-Chips entsprechen dem: Leicht ≈ 4+, Passend ≈ 2–3, Schwer ≈ 1, Limit = 0. Die meisten Sätze sollten mit 1–3 im Tank enden.'],
 'termE1rmTitle': ['e1RM – estimated one-rep max', 'e1RM – geschätztes Maximalgewicht'],
 'termE1rmBody': ['The weight you could probably lift exactly once, calculated from a set with more reps (e.g. 80 kg × 8 ≈ 101 kg). No need to test a real max.', 'Das Gewicht, das du vermutlich genau einmal schaffen würdest – berechnet aus einem Satz mit mehr Wiederholungen (z. B. 80 kg × 8 ≈ 101 kg). Ein echter Maximaltest ist nicht nötig.'],
 'termE1rmTip': ['Good for comparing progress across different weights and rep counts.', 'Ideal, um Fortschritt über verschiedene Gewichte und Wiederholungszahlen zu vergleichen.'],
 'termVdotTitle': ['VDOT – running fitness score', 'VDOT – Lauf-Fitnesswert'],
 'termVdotBody': ['A score by coach Jack Daniels derived from your race times. All running paces in your plan (easy, tempo, interval) are calculated from it.', 'Ein Wert nach Trainer Jack Daniels, berechnet aus deinen Wettkampfzeiten. Alle Lauftempos in deinem Plan (locker, Tempo, Intervall) werden daraus abgeleitet.'],
 'termVdotTip': ['+1 VDOT is roughly 1–2 % faster over any distance. It rises with consistent training and is updated when you run faster.', '+1 VDOT entspricht etwa 1–2 % schneller über jede Distanz. Er steigt mit regelmäßigem Training und wird aktualisiert, wenn du schneller läufst.'],
 'termFtpTitle': ['FTP – Functional Threshold Power', 'FTP – funktionelle Schwellenleistung'],
 'termFtpBody': ['The power (watts) you can hold on the bike for about one hour. Bike zones such as endurance, sweet spot and threshold are percentages of it.', 'Die Leistung (Watt), die du auf dem Rad etwa eine Stunde halten kannst. Radzonen wie Grundlage, Sweet Spot und Schwelle sind Prozentwerte davon.'],
 'termFtpTip': ['Without a power meter the plan uses heart rate and feel instead.', 'Ohne Wattmesser nutzt der Plan stattdessen Puls und Gefühl.'],
 'termCssTitle': ['CSS – Critical Swim Speed', 'CSS – kritische Schwimmgeschwindigkeit'],
 'termCssBody': ['Your threshold pace in the pool per 100 m, calculated from a 400 m and a 200 m time trial. Swim intervals are set relative to it.', 'Dein Schwellentempo im Becken pro 100 m, berechnet aus einem 400-m- und einem 200-m-Test. Schwimm-Intervalle werden relativ dazu vorgegeben.'],
 'termCssTip': ['Example: 400 m in 8:00 and 200 m in 3:40 → CSS ≈ 2:10 /100 m.', 'Beispiel: 400 m in 8:00 und 200 m in 3:40 → CSS ≈ 2:10 /100 m.'],
 'termSupersetTitle': ['Superset', 'Supersatz'],
 'termSupersetBody': ['Two (or three) exercises done back to back with only a short switch, then the full rest. The app pairs opposing muscles (e.g. press + row), so each recovers while the other works.', 'Zwei (oder drei) Übungen direkt nacheinander mit nur kurzem Wechsel, danach die volle Pause. Die App kombiniert gegensätzliche Muskeln (z. B. Drücken + Rudern), so erholt sich der eine, während der andere arbeitet.'],
 'termSupersetTip': ['Saves time without losing performance.', 'Spart Zeit, ohne Leistung zu kosten.'],
 'termAmrapTitle': ['AMRAP – as many reps as possible', 'AMRAP – so viele Wiederholungen wie möglich'],
 'termAmrapBody': ['On the last set do as many clean reps as you can – but stop one rep before failure. The app uses the result to correct your weights.', 'Im letzten Satz so viele saubere Wiederholungen wie möglich – aber eine Wiederholung vor dem Versagen aufhören. Die App korrigiert damit deine Gewichte.'],
 'termAmrapTip': ['Only appears when it helps: for new exercises and when you reach the top of the rep range.', 'Erscheint nur, wenn es hilft: bei neuen Übungen und wenn du das obere Ende des Bereichs erreichst.'],
 'termVolumeTitle': ['Volume', 'Volumen'],
 'termVolumeBody': ["Weight × reps of all working sets added up (warm-ups don't count). For bodyweight exercises the lifted share of your body weight counts.", 'Gewicht × Wiederholungen aller Arbeitssätze zusammengezählt (Aufwärmsätze zählen nicht). Bei Körpergewichtsübungen zählt der bewegte Anteil deines Körpergewichts.'],
 'termVolumeTip': ['More volume is not automatically better – what matters is progress over weeks.', 'Mehr Volumen ist nicht automatisch besser – entscheidend ist der Fortschritt über Wochen.'],
 'termPhaseTitle': ['Plan phases', 'Planphasen'],
 'termPhaseBody': ['Base: build endurance and technique, mostly easy. Build: more intensity. Peak: race-specific sessions. Taper: less volume before the race so you start fresh. Deload: a lighter week every 3–4 weeks so your body can adapt.', 'Grundlage: Ausdauer und Technik aufbauen, überwiegend locker. Aufbau: mehr Intensität. Spitze: wettkampfspezifische Einheiten. Tapering: weniger Umfang vor dem Wettkampf, damit du frisch startest. Entlastung: alle 3–4 Wochen eine leichtere Woche, damit sich der Körper anpasst.'],
 'termPhaseTip': ["Deload and taper weeks feel easy on purpose – don't make up for them.", 'Entlastungs- und Taperwochen fühlen sich bewusst leicht an – nicht nachholen.'],
 'termZonesTitle': ['Intensity zones', 'Intensitätszonen'],
 'termZonesBody': ["Training ranges from very easy to maximal, based on pace, heart rate or power. About 80 % of endurance training should be easy – that's what builds your base.", 'Belastungsbereiche von sehr locker bis maximal, über Tempo, Puls oder Leistung definiert. Etwa 80 % des Ausdauertrainings sollten locker sein – das baut deine Grundlage auf.'],
 'termZonesTip': ['Tap a zone in a workout for its exact range.', 'Tippe in einer Einheit auf eine Zone, um ihren genauen Bereich zu sehen.'],
}
